<template><div class="fm-page"><header class="fm-head"><div><span class="fm-kicker">个人账户</span><h1>个人信息</h1><p>更新登录邮箱或密码。修改密码后，其他设备上的旧登录会在会话到期后失效。</p></div></header><div class="grid-2">
  <section class="fm-card"><h2>登录邮箱</h2><p class="muted">同时用于密码找回。</p><form @submit.prevent="saveEmail"><label class="field"><span>邮箱</span><input v-model.trim="email" type="email" required/></label><div v-if="emailMessage" class="notice" :class="{error:emailFailed,ok:!emailFailed}">{{emailMessage}}</div><FmButton variant="primary" type="submit" :loading="savingEmail">保存邮箱</FmButton></form></section>
  <section class="fm-card"><h2>修改密码</h2><p class="muted">密码至少 6 位，请勿与上游 Key 使用相同内容。</p><form @submit.prevent="savePassword"><label class="field"><span>当前密码</span><input v-model="password.current_password" type="password" required/></label><label class="field"><span>新密码</span><input v-model="password.new_password" type="password" minlength="6" required/></label><div v-if="passwordMessage" class="notice" :class="{error:passwordFailed,ok:!passwordFailed}">{{passwordMessage}}</div><FmButton variant="primary" type="submit" :loading="savingPassword">更新密码</FmButton></form></section>
</div></div></template>
<script setup>import{reactive,ref}from"vue";import{api,session,toast}from"../api/client.js";import FmButton from"../ui/freemodel/components/FmButton.vue";const email=ref(session.user.email),password=reactive({current_password:"",new_password:""}),savingEmail=ref(false),savingPassword=ref(false),emailMessage=ref(""),passwordMessage=ref(""),emailFailed=ref(false),passwordFailed=ref(false);async function saveEmail(){savingEmail.value=true;try{session.user=await api("/api/me/profile",{method:"PUT",body:JSON.stringify({email:email.value})});emailMessage.value="邮箱已更新";emailFailed.value=false;toast(emailMessage.value,"success")}catch(e){emailMessage.value=e.message;emailFailed.value=true;toast(e.message,"error")}finally{savingEmail.value=false}}async function savePassword(){savingPassword.value=true;try{const v=await api("/api/me/password",{method:"PUT",body:JSON.stringify(password)});passwordMessage.value=v.message;passwordFailed.value=false;password.current_password="";password.new_password="";toast(v.message,"success")}catch(e){passwordMessage.value=e.message;passwordFailed.value=true;toast(e.message,"error")}finally{savingPassword.value=false}}</script><style scoped>.fm-card h2{margin:0 0 4px;font-size:19px}.fm-card form{margin-top:22px}</style>
